INSERT INTO `products` VALUES (1,1,1,'Anastroprime 1 mg','anastroprime-1-mg','Control E2 + Definici├│n Seca','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Anstroprime 1 mg</strong>┬áes anastrozol (Arimidex premium) de Eminence Labs (1 mg/tableta, 30 tabletas), AI no esteroide que inhibe enzima aromatasa (bloquea 80%+ conversi├│n andr├│genosÔåÆestr├│genos), vida media 40-50h, indispensable en ciclos aromatizantes para mantener E2 ├│ptimo (20-30 pg/ml).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Previene gyno/retenci├│n h├¡drica (f├¡sico seco/vascular), Ôåætestosterona libre (+fuerza/crecimiento muscular), Ôåôagua subcut├ínea (definici├│n \"hard\"), recuperaci├│n post-entreno mejorada, ratio T/E2 optimizado (libido/energ├¡aÔåæ). Dosis: 0.25-0.5 mg EOD (Test 500mg/sem), 0.5-1 mg EOD (Test 750mg+); basado en anal├¡ticas.</p>','',54.99,'USD','instock',1,'/static/img/anstroprime-1-mg-53421.webp','Anstroprime 1 mg: Control E2 + Definici├│n Seca','Anstroprime 1 mg: anastrozol AI bloquea aromatizaci├│n, elimina retenci├│n/gyno, potencia testo libre. ┬íF├¡sico vascular elite!',0,'2026-11-18 16:52:26','2026-11-18 18:38:36','EMI-ANT-001',14483,'https://anabolicgroup.com/product/anstroprime-1-mg/');
INSERT INTO `products` VALUES (2,1,2,'Boldeprime 200 mg','boldeprime-200-mg','Volumen Magro + Resistencia','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Boldeprime 200 mg</strong>┬áes undecilenato de boldenona (Equipoise premium) de Eminence Labs (200 mg/ml, 10 ampollas x 1 ml), derivado testosterona inyectable de acci├│n lenta (vida media 14 d├¡as), altamente anab├│lico (rating 100) con baja androgenia, perfecto para ciclos largos de volumen/recomp, promoviendo s├¡ntesis proteica sostenida, eritropoyesis (RBCÔåæ), apetito incrementado y retenci├│n nitr├│geno sin mucha retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa magra duradera (8-12kg ciclo), fuerza/resistenciaÔåæ, vascularidad notable, recuperaci├│n mejorada, inmunidad/col├ígeno reforzados, quema grasa leve. Dosis: 400-600 mg/semana (1-2 inyecciones, 12-16 semanas); stacks: + Test Long (base), + Deca (volumen), + Tren/Winstrol (recomp pro). Mujeres bajas dosis.</p>','',74.99,'USD','instock',1,'/static/img/boldeprime-200-mg-28457.webp','Boldeprime 200 mg: Volumen Magro + Resistencia','Boldeprime 200 mg: boldenona undecilenato para ganancias limpias (+8-12kg), vascularidad 3D y apetito voraz. 10 amps 1ml.',1,'2026-11-18 16:52:26','2026-11-18 17:34:29','EMI-VOL-002',14668,'https://anabolicgroup.com/product/boldeprime-200-mg/');
