','MetaPrime 10 mg (Dianabol)','<b>MetaPrime 10 mg</b> de <b>Eminence Labs</b>: tabletas de Methandienone (Dianabol) 10 mg, caja de 50 unidades. Producto de uso referencial; consulta a tu m├®dico antes de consumir.',15,'2026-11-18 16:52:26','2026-11-18 18:38:36','EMI-VOL-016',14511,'https://anabolicgroup.com/product/metaprime-10-mg/');
INSERT INTO `products` VALUES (17,2,1,'Androlic 25 mg - Oximetolona','androlic-25-mg-oximetolona','Volumen Extremo + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Androlic 25 mg</strong>┬áes oximetolona premium en tabletas orales de 25 mg, el anab├│lico oral m├ís potente para ciclos de volumen m├íximo y fuerza sobrehumana en bodybuilding avanzado. Estimula eritropoyesis (m├ís gl├│bulos rojos), s├¡ntesis proteica extrema y retenci├│n anab├│lica de agua para hipertrofia r├ípida (10-15 kg en 4 semanas), pumps intensos y r├®cords personales (+40-60% en compuestos pesados como squat y bench).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa muscular full inmediata, apetito insaciable, recuperaci├│n en horas, vascularidad potente pese a retenci├│n y rendimiento elite. Dosis t├¡pica: 50-100 mg/d├¡a dividido (principiantes 25-50 mg), ciclos cortos 3-5 semanas por hepatotoxicidad alta. Stacks ideales: + Testosterona/Deca (masa nuclear), + Trenbolona (fuerza seca), solo para shock therapy o puentes. M├®dicamente para anemias o p├®rdida muscular severa.</p>','',54.99,'USD','instock',1,'/static/img/androlic-25-mg-oximetolona-294.png','Androlic 25 mg - Oximetolona: Volumen Extremo + Fuerza','Androlic 25 mg: oximetolona para ganancias masivas de m├║sculo y fuerza brutal. Oral volumen r├ípido.',16,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-001',14053,'https://anabolicgroup.com/product/androlic-25-mg-oximetolona/');
INSERT INTO `products` VALUES (18,2,2,'Boldenona 250 mg','boldenona-250-mg','Volumen Magro + Resistencia','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Boldenona 250 mg</strong>┬áes boldenona undecilenato (Equipoise gen├®rico) inyectable (250 mg/ml vial 10ml), derivado testosterona de liberaci├│n ultra-lenta (3-4 semanas), perfecta para ciclos largos de volumen magro, incrementando apetito, s├¡ntesis proteica, retenci├│n nitr├│geno, IGF-1 y eritropoyesis para ganancias progresivas (10-15 kg quality en 12-16 semanas) con m├¡nima aromatizaci├│n y retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa muscular sostenida/vascular, fuerza/resistencia notable (+30% endurance), recuperaci├│n elite, perfil seguro (bajo androg├®nico), inmunidad reforzada y vascularidad progresiva. Dosis hombres: 400-600 mg/semana IM, mujeres: 50-100 mg/semana; ciclos 12-20 semanas. Stacks: + Test/Deca (masa extrema), + Tren (recomp), solo bulk lento/TRT.</p>','',64.99,'USD','instock',1,'/static/img/boldenona-250-mg-51658.webp','Boldenona 250 mg: Volumen Magro + Resistencia','Boldenona 250 mg: undecilenato para m├║sculo limpio, fuerza sostenida y apetito voraz.┬á┬íGanancias de calidad elite!',17,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-002',14556,'https://anabolicgroup.com/product/boldenona-250-mg/');
INSERT INTO `products` VALUES (19,2,1,'Clenbuterol 0.04 mg','clenbuterol-0-04-mg','Quema Grasa R├ípida + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Clenbuterol 0.04 mg</strong>┬á(40 mcg/tableta) es un agonista beta-2 termog├®nico de acci├│n r├ípida, perfecto para fases de corte agresivo en bodybuilding, elevando metabolismo basal +10-20%, estimulando lip├│lisis selectiva (p├®rdida 0.5-1.5 kg grasa/semana) y preservando masa magra mediante efectos anticatab├│licos, con mejora notable en capacidad aer├│bica y enfoque mental para entrenamientos intensos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Reducci├│n grasa abdominal/visceral acelerada, supresi├│n apetito, stamina cardiovascular superior (+30% cardio), pumps vasculares notables y resultados visibles en 7-10 d├¡as. Protocolo: mujeres 20-60 mcg/d├¡a, hombres 40-120 mcg/d├¡a (ramp-up 2 semanas on/2 off para evitar tolerancia); total ciclo 4-8 semanas. Stacks: + T3/Keto (quema extrema), + Anavar/Winstrol (corte seco), + Test (recomp).</p>','',64.99,'USD','instock',1,'/static/img/clenbuterol-0-04-mg-47339.webp','Clenbuterol 0.04 mg: Quema Grasa R├ípida + Definici├│n','Clenbuterol 0.04 mg: termog├®nico potente para grasa rebelde, energ├¡a elite y m├║sculo preservado. Ciclos 2x2 semanas.',18,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-QUI-003',14286,'https://anabolicgroup.com/product/clenbuterol-0-04-mg/');
INSERT INTO `products` VALUES (20,2,2,'Decaland 200 mg','decaland-200-mg','Volumen Masivo + Articulaciones','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Decaland 200 mg</strong>┬áes decanoato de nandrolona de Landerlan (200 mg/ml vial 5ml), esteroide altamente anab├│lico de liberaci├│n lenta (vida media 6-12 d├¡as), perfecto para ciclos largos de volumen m├íximo, incrementando s├¡ntesis proteica, retenci├│n de nitr├│geno, producci├│n de gl├│bulos rojos y col├ígeno articular para ganancias s├│lidas (15-25 kg en 12-16 semanas) y lubricaci├│n superior de articulaciones/tendones.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Hipertrofia extrema (fullness muscular notable), fuerza progresiva (+40-60% compuestos pesados), recuperaci├│n elite, apetito voraz, densidad ├│sea reforzada y perfil seguro (bajo androg├®nico vs testosterona). Dosis hombres: 200-400 mg/semana IM, mujeres: evitar; ciclos 12-20 semanas. Stacks: + Test/Dianabol (masa nuclear), + EQ (calidad), solo soporte terap├®utico.</p>','',74.99,'USD','instock',1,'/static/img/decaland-200-mg-21517.webp','Decaland 200 mg: Volumen Masivo + Articulaciones','Decaland 200 mg: decanoato nandrolona para ganancias masivas m├║sculo, fuerza y recuperaci├│n articular. Acci├│n 3 semanas.',19,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-004',14557,'https://anabolicgroup.com/product/decaland-200-mg/');
INSERT INTO `products` VALUES (21,2,2,'Drostanolona Propionato 10 ml','drostanolona-propionato-10ml','Definici├│n Dura + Fuerza Seca','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Drostanolona Propionato 10 ml</strong>┬á(100-150 mg/ml vial) es un derivado DHT inyectable potente para fases de corte pre-competici├│n, promoviendo dureza muscular extrema, reducci├│n de grasa subcut├ínea y vascularidad 3D sin retenci├│n de agua ni aromatizaci├│n (propiedades anti-estrog├®nicas naturales). Act├║a incrementando fuerza seca, retenci├│n de nitr├│geno y definici├│n, ideal para physiques ya magros (8-12% BF), con ganancias de dureza notable en 4-6 semanas y sinergia como endurecedor en stacks.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Esculpe m├║sculo gran├¡tico (densidad + vascularidad), fuerza m├íxima sin bulk (+20-30% en presses), quema grasa preservando magro, mejora libido/agresividad controlada, recuperaci├│n elite y anti-E2 (reduce gyno en ciclos). Dosis: hombres 300-600 mg/semana (EOD/M-W-F IM), mujeres 50-100 mg/semana; ciclos 6-12 semanas. Stacks: + Test/Primo (recomp seguro), + Tren/Winstrol (corte pro), + GH/Peps (elite) o solo para polish final. M├®dicamente para c├íncer de mama o caquexia.</p>','',78.99,'USD','instock',1,'/static/img/drostanolona-propionato-10ml-41470.png','Drostanolona Propionato 10ml: Definici├│n Dura + Fuerza Seca','Drostanolona Propionato 10ml: Masteron para dureza muscular, quema grasa y vascularidad elite. Anti-estrog├®nico.',20,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-DEF-005',14095,'https://anabolicgroup.com/product/drostanolona-propionato-10ml/');
INSERT INTO `products` VALUES (22,2,2,'Durateston Plus Gold 10 ml','durateston-plus-gold-10ml','Volumen Sostenido + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Durateston Plus Gold 10ml</strong>┬áes una mezcla inyectable premium de Landerlan Gold (250 mg/ml: testosterona propionato 50 mg, fenilpropionato 100 mg, isocaproato 100 mg), dise├▒ada para liberaci├│n sin interrupciones durante 2-3 semanas por dosis, maximizando anabolismo constante, hipertrofia progresiva (10-20 kg en 12 semanas) y fuerza explosiva en ciclos de volumen sostenido para bodybuilding profesional. Su perfil multi-├®ster evita picos/valores bajos, optimizando ganancias magras con retenci├│n moderada.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Crecimiento muscular continuo (pecho/espalda/piernas), fuerza m├íxima (+30-50% compuestos), libido/energ├¡a elevada, recuperaci├│n superior, apetito controlado y sinergia elite en stacks. Dosis: 500-1000 mg/semana IM (principiantes 1 ml/semana), ciclos 10-16 semanas. Stacks: solo (base ideal), + Deca/EQ (masa vascular), + Dianabol (kickstart), + Tren (pro) o + HGH (elite). M├®dicamente para hipogonadismo/TRT (250 mg/3 semanas).</p>','',74.99,'USD','instock',1,'/static/img/durateston-plus-gold-10ml-99578.png','Durateston Plus Gold 10ml: Volumen Sostenido + Fuerza','Durateston Plus Gold 10ml: mezcla testosteronas para masa muscular continua, fuerza elite y recuperaci├│n. 250mg/ml multi-├®ster.',21,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-006',14092,'https://anabolicgroup.com/product/durateston-plus-gold-10ml/');
INSERT INTO `products` VALUES (23,2,1,'Metenolona Acetato 25 mg','metenolona-acetato-25-mg','Definici├│n Limpia + Masa Magra','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Metenolona Acetato 25 mg</strong>┬á(Primobolan oral) es un derivado de DHT suave en tabletas de 25 mg, perfecto para ciclos de corte, recomposici├│n y ganancias de masa muscular magra sin retenci├│n de agua ni efectos androg├®nicos agresivos. Aumenta retenci├│n de nitr├│geno, s├¡ntesis proteica y lip├│lisis selectiva, preservando m├║sculo en d├®ficits cal├│ricos mientras mejora dureza, vascularidad y definici├│n (ideal pre-competici├│n, -4-8% grasa en 8-12 semanas).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa magra de calidad (3-7 kg retenidos), fuerza progresiva (+15-25% sin bulk), quema grasa preservando m├║sculo, perfil seguro (bajo impacto hep├ítico/androg├®nico), recuperaci├│n superior y sinergia en stacks. Dosis: mujeres 25-75 mg/d├¡a, hombres 50-150 mg/d├¡a dividido; ciclos 8-12 semanas. Stacks: + Test/Anavar (recomp seguro), + Winstrol/Masteron (corte pro), + Tren (elite) o solo para definici├│n limpia. M├®dicamente para caquexia, osteoporosis o anemia.</p>','',64.99,'USD','instock',1,'/static/img/metenolona-acetato-25-mg.webp','Metenolona Acetato 25 mg: Definici├│n Limpia + Masa Magra','Metenolona Acetato 25 mg: Primobolan oral para m├║sculo seco, definici├│n elite y fuerza sin agua. Bajo riesgo.',22,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-007',14071,'https://anabolicgroup.com/product/metenolona-acetato-25mg/');
INSERT INTO `products` VALUES (24,2,2,'Metenolona Enantato 100 mg','metenolona-enantato-100-mg','Masa Limpia','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Metenolona Enantato 100 mg</strong>┬áes metenolona enantato (Primobolan premium, 100 mg/ml), derivado DHT inyectable de acci├│n prolongada (vida media 10-14 d├¡as), altamente anab├│lico con m├¡nima androgenia/no aromatizaci├│n, perfecto para principiantes/mujeres y ciclos de recomp/volumen limpio promoviendo s├¡ntesis proteica sostenida, preservaci├│n muscular y definici├│n natural.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias magras duraderas (5-8kg ciclo), fuerza progresiva sin bulk, quema grasa leve, inmunidad reforzada, col├ígenoÔåæ (joints), seguridad perfil (baja toxicidad). Dosis hombres: 400-600 mg/semana (10-12 semanas); mujeres: 50-100 mg/semana. Stacks: + Test (base), + Anavar/Winstrol (corte), + Deca (volumen suave).</p>','',99.99,'USD','instock',1,'/static/img/metenolona-enantato-100-mg.webp','Metenolona Enantato 100 mg: Masa Limpia','Metenolona Enantato 100 mg: Primobolan para m├║sculo seco, fuerza suave y definici├│n sin agua. ┬íCalidad elite!',23,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-008',14773,'https://anabolicgroup.com/product/metenolona-enantato-100-mg/');
INSERT INTO `products` VALUES (25,2,2,'Nandrolona Fenil NPP 100 mg','nandrolona-fenil-npp-100-mg','Volumen R├ípido + Articulaciones','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Nandrolona Fenil NPP 100 mg</strong>┬áes fenilpropionato de nandrolona (NPP premium) inyectable (100 mg/ml vial 10ml), versi├│n corta del Deca (vida media 2-4 d├¡as) perfecta para ciclos de volumen limpio con control preciso, promoviendo s├¡ntesis proteica intensa, retenci├│n de nitr├│geno y lubricaci├│n articular superior para ganancias notables (6-12 kg magros en 8 semanas) sin retenci├│n excesiva.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo denso sin hinchaz├│n, col├ígeno/tendones reforzados (ideal cargas pesadas), eritropoyesis (+oxigenaci├│n), inmunidad elevada, perfil anab├│lico superior y menos progest├ígenos que Deca larga. Dosis hombres: 200-400 mg/semana IM EOD, mujeres: 50-100 mg/semana; ciclos 8-12 semanas. Stacks: + Test Prop (masa conjunta), + Dianabol (kickstart), solo soporte articular.</p>','',74.99,'USD','outofstock',0,'/static/img/nandrolona-fenil-npp-100-mg.webp','Nandrolona Fenil NPP 100 mg: Volumen R├ípido + Articulaciones','Nandrolona Fenil NPP 100 mg: acci├│n r├ípida para m├║sculo magro, recuperaci├│n articular y fuerza s├│lida. ┬íGanancias sin dolor!',24,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-009',14577,'https://anabolicgroup.com/product/nandrolona-fenil-npp-100-mg/');
