INSERT INTO `products` VALUES (27,2,1,'Oxandroland 5 mg - Oxandrolona','oxandroland-5-mg-oxandrolona','Corte Seco + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Oxandroland 5 mg</strong>┬áes oxandrolona (Anavar) premium de Landerlan en tabletas de 5 mg, el anab├│lico oral m├ís seguro del mercado para fases de corte, recomposici├│n y ganancias de fuerza magra, especialmente para mujeres y principiantes. Bajo androg├®nico/hepatot├│xico m├¡nimo, acelera lip├│lisis, preserva m├║sculo en d├®ficit cal├│rico y otorga vascularidad/dureza sin retenci├│n h├¡drica ni virilizaci├│n notable.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Reducci├│n grasa (4-8% BF en 6 semanas), fuerza sostenida (+10-20% sin volumen), m├║sculo compacto (2-4 kg retenidos), pumps elite y recuperaci├│n superior. Ideal para mujeres (5-15 mg/d├¡a), hombres (20-40 mg/d├¡a): solo (corte seguro), + Winstrol (dureza extrema), + Test bajo (recomp), + Clen/T3 (quema grasa) o + Primo (elite). M├®dicamente para osteoporosis, quemaduras o p├®rdida muscular.</p>','',74.99,'USD','instock',1,'/static/img/oxandroland-5-mg-oxandrolona.png','Oxandroland 5 mg - Oxandrolona: Corte Seco + Fuerza','Oxandroland 5 mg: oxandrolona segura para definici├│n muscular, fuerza sin agua y recuperaci├│n.',26,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-DEF-011',14047,'https://anabolicgroup.com/product/oxandroland-5mg-oxandrolona/');
INSERT INTO `products` VALUES (28,2,2,'Testenat Depot - 250 mg','testenat-depot-250-mg','Ganancia de M├║sculo + Fuerza M├íxima','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Testenat Depot 250 mg/ml</strong>┬áes cipionato de testosterona premium de alta calidad (250 mg por ml en ampolla de 1 ml o 2 ml), el esteroide inyectable definitivo para ciclos de volumen masivo, hipertrofia extrema y potencia sobrehumana en bodybuilding profesional. Su ├®ster largo proporciona liberaci├│n sostenida durante 10-14 d├¡as, estabilizando niveles hormonales para maximizar s├¡ntesis proteica, retenci├│n de nitr├│geno y ganancias de 8-15 kg de m├║sculo puro en 10-12 semanas, con m├¡nima retenci├│n h├¡drica comparado a enantato.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios principales</strong>: Explosi├│n de fuerza (aumentos del 25-40% en levantamientos), hipertrofia r├ípida en hombros/pecho/espalda, mejora dr├ística en libido, energ├¡a y agresividad en entrenamiento, fortalecimiento ├│seo/articular y recuperaci├│n post-entreno en horas. Ideal para stacks potentes: solo (400-600 mg/semana principiantes), + Deca (masa monstruosa), + Trenbolona (definici├│n dura), + EQ (volumen vascular) o + Primobolan (calidad elite). Indicado m├®dicamente para TRT (100-200 mg/semana) o hipogonadismo.</p>','',74.99,'USD','instock',1,'/static/img/testenat-depot-250-mg.webp','Testenat Depot - 250 mg - Ganancia de M├║sculo + Fuerza M├íxima','Testenat Depot 250 mg cipionato: masa muscular explosiva, fuerza brutal y recuperaci├│n top. Acci├│n prolongada para ciclos.',27,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-012',13990,'https://anabolicgroup.com/product/testenat-depot-250-mg/');
INSERT INTO `products` VALUES (29,2,2,'Testoland Depot - 200 mg - Cipionato','testoland-depot-200-mg-cipionato','Ganancia de M├║sculo + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Testoland 200 mg Depot</strong>┬áde Landerlan es cipionato de testosterona puro (200 mg/ml en ampolla de 2 ml), la base ideal para ciclos de volumen masivo, aumento de fuerza explosiva y recuperaci├│n superior en bodybuilding avanzado. Su ├®ster largo asegura liberaci├│n sostenida (hasta 2 semanas por dosis), manteniendo niveles hormonales ├│ptimos para s├¡ntesis proteica intensiva, hipertrofia muscular notable (5-10 kg en 8-12 semanas) y menor aromatizaci├│n que otros ├®steres.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias s├│lidas de masa magra, eleva fuerza m├íxima (bench +20-30%), mejora libido/energ├¡a, fortalece huesos y articulaciones. Perfecto solo (principiante: 400 mg/semana) o stackeado: + Deca-Durabolin (masa extrema), + Boldenona (volumen seco), + Anavar/Winstrol (definici├│n) o + HGH para elite. Indicado para hipogonadismo, TRT o pubertad retardada (200-600 mg/semana IM).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"></p>','',74.99,'USD','instock',1,'/static/img/testoland-depot-200-mg-cipionato.webp','Testoland Depot - 200 mg - Cipionato - Ganacia de M├║sculo + Fuerza','Testoland Depot 200 mg cipionato de testosterona: gana m├║sculo, fuerza y volumen r├ípido. Ciclos bodybuilding.',28,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-013',13987,'https://anabolicgroup.com/product/testoland-depot-200-mg-cipionato/');
INSERT INTO `products` VALUES (30,2,2,'Testosterona Propionato 100 mg','testosterona-propionato-100-mg','Corte R├ípido + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Testosterona Propionato 100 mg</strong>┬áes testosterona propionato (Test Prop premium) de Landerlan (100 mg/ml, 10 ampollas x 1 ml), ├®ster corto inyectable (vida media 2-3 d├¡as), perfecto para fases de corte/pre-competici├│n y ciclos \"blast\", promoviendo s├¡ntesis proteica explosiva, fuerza sin agua y definici├│n con control fino de niveles hormonales.<span class=\"inline-flex\" aria-label=\"Testosterona Propionato 100 mg Fco. Amp. x 10ml - Landerlan\" data-state=\"closed\">ÔÇï</span></p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Fuerza explosiva (+30%), vascularidad/dureza, quema grasa androg├®nica, menos retenci├│n (vs ├®steres largos), r├ípida recuperaci├│n PCT, vers├ítil stacks. Dosis: 100 mg EOD (300-500 mg/semana, 6-8 semanas); stacks: + Winstrol/Masteron (shred), + Tren Ace (stage pro).</p>','',64.99,'USD','instock',1,'/static/img/testosterona-propionato-100-mg.webp','Testosterona Propionato 100 mg: Corte R├ípido + Definici├│n','Test Prop 100 mg: testosterona r├ípida para fuerza seca, vascularidad y menos retenci├│n. 10 amps 1ml.',29,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-014',14580,'https://anabolicgroup.com/product/testosterona-propionato-100-mg/');
INSERT INTO `products` VALUES (31,2,2,'Trembolona Enantato 200 mg','trembolona-enantato-200-mg','Masa + Fuerza Nuclear','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Trembolona Enantato 200 mg</strong>┬áes enantato de trembolona (Tren E premium, 200 mg/ml vial 10 ml), esteroide 19-nor inyectable de liberaci├│n lenta (vida media 8-10 d├¡as), 5x m├ís anab├│lico/androg├®nico que testosterona, perfecto para ciclos largos de volumen/recomp/corte promoviendo s├¡ntesis proteica extrema, lip├│lisis agresiva, dureza gran├¡tica y eficiencia cal├│rica sin retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias magras (10-15kg ciclo), fuerza sobrehumana (+50% lifts), vascularidad 3D, quema grasa preservando m├║sculo, IGF-1Ôåæ, resistencia brutal. Dosis: 400-600 mg/semana (1-2 iny/semana, 10-12 semanas); stacks: + Test E (base), + Deca (volumen), + Masteron/Winstrol (stage).</p>','',74.99,'USD','outofstock',0,'/static/img/trembolona-enantato-200-mg.webp','Trembolona Enantato 200 mg: Masa + Fuerza Nuclear','Trembolona Enantato 200 mg: tren E para m├║sculo rocoso, venas 3D, lip├│lisis brutal. Vial 10ml.',30,'2026-11-18 16:52:26','2026-11-18 17:34:29','LAN-VOL-015',14599,'https://anabolicgroup.com/product/trembolona-enantato-200-mg/');
