INSERT INTO `products` VALUES (40,3,1,'Arimidext 1 mg','arimidext-1-mg','Control Estr├│genos + Seco','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Arimidex 1 mg</strong>┬á(anastrozol) es un inhibidor de aromatasa potente en tabletas orales de 1 mg, esencial para bodybuilders en ciclos con compuestos aromatizantes (testosterona, Dianabol, Deca), bloqueando la conversi├│n de andr├│genos a estr├│genos en hasta 80%, previniendo ginecomastia, retenci├│n h├¡drica, grasa emocional y elevaci├│n de prolactina para un f├¡sico seco, duro y vascular durante volumen o corte.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Control total E2 (sensibilidad v├¡a sangre), mejora definici├│n muscular/libido, aumenta testosterona libre disponible, recuperaci├│n elite y sinergia en PCT/TRT. Dosis t├¡pica: 0.25-0.5 mg EOD (principiantes), 0.5-1 mg/d├¡a en ciclos fuertes; durante 4-8 semanas o seg├║n labs. Stacks: con Test/Dbol (anti-gyno), Tren/Deca (prolactina), solo en TRT o PCT bridge. M├®dicamente para c├íncer mama post-menopausia (1 mg/d├¡a).</p>','',59.99,'USD','instock',1,'/static/img/arimidex-1-mg-anastrozol-74881.webp','Arimidex 1 mg Anastrozol: Control Estr├│genos + Seco','Arimidex 1 mg: reduce estr├│genos, previene gyno y retenci├│n en ciclos. Definici├│n elite. Dosis precisa bodybuilding.',39,'2026-11-18 16:52:26','2026-11-18 18:38:36','XTL-ANT-001',14293,'https://anabolicgroup.com/product/arimidext-1mg/');
INSERT INTO `products` VALUES (41,3,2,'Boldeplex 200 mg','boldeplex-200-mg','Volumen Magro + Resistencia','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Boldeplex 200 mg</strong>┬áes boldenona undecilenato (Equipoise gen├®rico) de XT Labs (200 mg/ml vial 10ml), derivado testosterona de liberaci├│n ultra-lenta (3-4 semanas), perfecto para ciclos largos de volumen magro, incrementando apetito, s├¡ntesis proteica, retenci├│n nitr├│geno, IGF-1 y eritropoyesis para ganancias progresivas (8-12 kg quality en 12-16 semanas) con m├¡nima retenci├│n h├¡drica y aromatizaci├│n baja.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa muscular sostenida/densa, fuerza/resistencia vascular (+30% endurance), recuperaci├│n elite, perfil seguro (bajo androg├®nico), inmunidad reforzada y vascularidad notable. Dosis hombres: 400-600 mg/semana IM, mujeres: 50-100 mg/semana; ciclos 12-20 semanas. Stacks: + Test/Deca (masa extrema), + Tren (recomp), solo para bulk lento o TRT. M├®dicamente para anemia.</p>','',64.99,'USD','outofstock',0,'/static/img/boldeplex-200-mg-40899.png','Boldeplex 200 mg: Volumen Magro + Resistencia','Boldeplex 200 mg: boldenona undecilenato para m├║sculo limpio, fuerza sostenida y apetito voraz. ┬íGanancias de calidad!',40,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-002',14234,'https://anabolicgroup.com/product/boldeplex-200-mg/');
INSERT INTO `products` VALUES (42,3,1,'Cardarine 10 mg','cardarine-10-mg','Resistencia + Quema Grasa','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Cardarine 10 mg</strong>┬á es un agonista PPAR╬┤ oral en tabletas de 10 mg, revolucionario para aumentar resistencia cardiovascular, oxidaci├│n de ├ícidos grasos y eficiencia mitocondrial, permitiendo sesiones de cardio/hipertrofia m├ís largas (hasta +50% tiempo entreno), quema grasa sostenida (1-2 kg/semana) y preservaci├│n muscular anticatab├│lica sin estimulantes ni supresi├│n hormonal.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Endurance sobrehumana (maratones gym), metabolismo basal +10-20%, lip├│lisis selectiva (grasa visceral), recuperaci├│n muscular r├ípida, perfiles lip├¡dicos mejorados y sinergia con SARMs/esteroides. Dosis: 10-20 mg/d├¡a (principiantes 10 mg), ciclos 8-12 semanas (sin PCT). Stacks: + Ligandrol/Ostarine (recomp), + Clen/T3 (corte extremo), + Test (volumen aer├│bico) o solo para cardio elite.</p>','',64.99,'USD','outofstock',0,'/static/img/cardarine-10-mg-46329.webp','Cardarine 10 mg : Resistencia + Quema Grasa','Cardarine 10 mg: potencia endurance, acelera metabolismo y quema grasa preservando m├║sculo. Entrenos ├®picos. ┬íRendimiento imparable!',41,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-QUI-003',14268,'https://anabolicgroup.com/product/cardarine-10-mg/');
INSERT INTO `products` VALUES (43,3,1,'Clembutrex 40 mcg','clembutrex-40-mcg','Quema Grasa + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Clenbutrex HCL 0.40 mg</strong>┬áes clenbuterol hidrocloruro de XT Labs (0.40 mg/tableta = 400 mcg, 60 tabletas), agonista beta-2 adren├®rgico (vida activa 25-35h) que estimula termog├®nesis (+temperatura corporal), metabolismo basal (+10%) y oxidaci├│n grasa directa mientras bloquea catabolismo muscular, ideal para definici├│n/recomp.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Lip├│lisis acelerada (200-400 kcal extra/d├¡a), definici├│n vascular, VO2 maxÔåæ (resistencia cardio +15%), energ├¡a/pumps intensos, anticatab├│lico (preserva masa magra), broncodilatador (mejor oxigenaci├│n). Protocolo piramidal 2 semanas on/off: 0.40 mg ÔåÆ pico 1.2 mg/d├¡a dividido;┬á<strong>stack Ketotifeno</strong>┬á(2mg/noche) para uso continuo.</p>','',59.99,'USD','instock',1,'/static/img/clenbutrex-hcl-0-40-mg-58003.webp','Clenbutrex HCL 0.40 mg: Quema Grasa + Definici├│n','Clenbutrex HCL 0.40 mg: clenbuterol beta-2 para metabolismo Ôåæ10%, lip├│lisis (0.5kg/semana) y preservaci├│n m├║sculo.',42,'2026-11-18 16:52:26','2026-11-18 18:38:36','XTL-QUI-004',14602,'https://anabolicgroup.com/product/clenbutrex-hcl-0-40-mg/');
INSERT INTO `products` VALUES (44,3,1,'Clembutrex Ultra 60 mcg','clembutrex-ultra-60-mcg','Quema Grasa + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Clenbutrex Ultra 0.60 mg</strong> es clenbuterol hidrocloruro ultra concentrado de XT Labs (0.60 mg/tableta, 90 tabletas), agonista beta-2 potente (40x efedrina) que eleva metabolismo basal +10-20%, temperatura corporal (termog├®nesis 200-400 kcal/d├¡a extra) y lip├│lisis selectiva, ideal para fases de corte pre-competici├│n preservando masa magra v├¡a anticatabolismo.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: P├®rdida grasa acelerada (0.5-1kg/semana), definici├│n vascular/marcada, VO2 maxÔåæ (+10-15% resistencia), apetito suprimido, pumps/energ├¡a intensos, no androg├®nico (mujeres seguro). Protocolo 2 semanas on/off: Inicio 0.20 mg ÔåÆ pico 0.80-1.2 mg/d├¡a dividido; stacks: + T3/Ketotifeno (prolonga sensibilidad), + Winstrol/Anavar (shred pro).</p>','',64.99,'USD','instock',1,'/static/img/clenbutrex-ultra-0-60-mg-10370.webp','Clenbutrex Ultra 0.60 mg: Quema Grasa + Definici├│n','Clenbutrex Ultra 0.60 mg: clenbuterol potenciado para lip├│lisis brutal (1kg/semana), m├║sculos marcados y energ├¡a.',43,'2026-11-18 16:52:26','2026-11-18 18:38:36','XTL-QUI-005',14603,'https://anabolicgroup.com/product/clenbutrex-ultra-0-60-mg/');
INSERT INTO `products` VALUES (45,3,2,'Decaplex 300 mg','decaplex-300-mg','Volumen Masivo + Articulaciones','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Decaplex 300 mg</strong>┬áes decanoato de nandrolona (Deca-Durabolin gen├®rico) de XT Labs (300 mg/ml vial 10ml), esteroide altamente anab├│lico de liberaci├│n lenta (vida media 6-12 d├¡as), perfecto para ciclos largos de volumen m├íximo, incrementando s├¡ntesis proteica, retenci├│n de nitr├│geno, producci├│n de gl├│bulos rojos y col├ígeno articular para ganancias s├│lidas (12-20 kg en 12-16 semanas) y lubricaci├│n de articulaciones/tendones.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Hipertrofia extrema (fullness muscular), fuerza progresiva (+40-60% compuestos pesados), recuperaci├│n superior, apetito voraz, densidad ├│sea reforzada y perfil seguro (bajo androg├®nico vs testosterona). Dosis hombres: 300-600 mg/semana IM, mujeres: evitar; ciclos 12-20 semanas. Stacks: + Test/Dianabol (masa nuclear), + EQ (calidad), solo para soporte terap├®utico. M├®dicamente para anemia/osteoporosis/caquexia.</p>','',64.99,'USD','outofstock',0,'/static/img/decaplex-300-mg-49350.webp','Decaplex 300 mg : Volumen Masivo + Articulaciones','Decaplex 300 mg: nandrolona decanoato para ganancias masivas m├║sculo, fuerza y recuperaci├│n articular.',44,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-006',14227,'https://anabolicgroup.com/product/decaplex-300-mg/');
INSERT INTO `products` VALUES (46,3,2,'Gentropin 210 UI','gentropin-210-ui','Masa Magra + Recuperaci├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Gentropin 210 UI</strong>┬áes somatropina (HGH humana recombinante) de alta pureza en kit de 7 viales x 30 UI (total 210 UI), la hormona de crecimiento bioid├®ntica para ciclos avanzados de hipertrofia magra, lip├│lisis acelerada y recuperaci├│n superior, incrementando IGF-1 hasta 300%, promoviendo proliferaci├│n celular, retenci├│n nitr├│geno y metabolismo proteico para ganancias compuestas (5-10 kg magros + -8% grasa corporal en 3-6 meses).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo denso/sat├®lites celulares, quema grasa visceral (sin catabolismo), articulaciones lubricadas, piel rejuvenecida, sue├▒o profundo REM, inmunidad reforzada y sinergia anab├│lica extrema. Protocolo: 2-6 UI/d├¡a SQ (ma├▒ana/noche), ciclos 3-6 meses + 1-2 meses off. Stacks: + Test/Insulina (masa pro), + T4/T3 (metabolismo), solo anti-aging (1-2 UI) o con AAS (4+ UI).</p>','',350.00,'USD','instock',1,'/static/img/gentropin-210-ui-89811.png','Gentropin 210 UI: Masa Magra + Recuperaci├│n','Gentropin 210 UI: HGH somatropina para m├║sculo denso, quema grasa y sue├▒o reparador. 7 viales 30UI.',45,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-GH-007',14309,'https://anabolicgroup.com/product/gentropin-210ui/');
INSERT INTO `products` VALUES (47,3,2,'HCG 10.000 UI','hcg-10-000-ui','Recuperaci├│n de Testosterona','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>HCG 10.000 UI</strong>┬áes Gonadotropina Cori├│nica Humana liofilizada (10.000 Unidades Internacionales vial), an├íloga de LH que estimula c├®lulas de Leydig para producci├│n end├│gena de testosterona (aumentos 50-100% en hipogonadismo), previniendo/siendo atrofia testicular durante ciclos esteroides y acelerando recuperaci├│n HPTA en PCT, manteniendo fertilidad y masa muscular post-ciclo.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Restauraci├│n hormonal natural, test├¡culos funcionales (evita shrinkage), mejora libido/esperma, puente ciclos, sinergia TRT y menos supresi├│n que SERMs solos. Protocolo PCT: 1000-2000 UI EOD x 2 semanas (total 10k-20k UI); durante ciclo: 250-500 UI 2x/semana. Reconstituir con BAC water, usar IM/SQ. Combinar Nolva/Clomid para PCT completo.</p>','',74.99,'USD','instock',1,'/static/img/hcg-10-000-ui.webp','HCG 10.000 UI | Recuperaci├│n de Testosterona','HCG 10.000 UI: restaura testosterona natural, previene atrofia testicular en PCT. Fertilidad elite.',46,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-REC-008',14299,'https://anabolicgroup.com/product/hcg-10-000-ui/');
INSERT INTO `products` VALUES (48,3,2,'Hutrope 100 IU','hutrope-100-iu','Masa Magra + Quema Grasa','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Hutrope 100 IU</strong>┬áes somatropina (HGH farmac├®utica) recombinante (kit 100 UI total, pen/cartruchos), hormona polip├®ptido 191 aa id├®ntica humana que estimula h├¡gadoÔåÆIGF-1, promoviendo hiperplasia/hipertrofia muscular, lip├│lisis visceral, col├ígeno/tendones, inmunidad y juventud celular, el \"fuente de la eterna juventud\" para bodybuilding.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Masa magra permanente (+5-10kg a├▒o), grasa Ôåô (15-20% BF), recuperaci├│n lesiones 70% m├ís r├ípida, piel el├ística/juventud, sue├▒o profundo, energ├¡a/vitalidadÔåæ, huesos/densidadÔåæ, libido. Dosis: 2-4 UI/d├¡a principiantes (ma├▒ana + post-entreno SC), 4-8 UI avanzados (dividido); stacks: + Insulina (bulk), + T3/T4 (corte), + AAS (sinergia). Ciclos 5on/2off m├¡nimo 6 meses.</p>','',215.00,'USD','instock',1,'/static/img/hutrope-100-iu-69896.webp','Hutrope 100 IU: Masa Magra + Quema Grasa','Hutrope 100 IU: HGH somatropina para hipertrofia, lip├│lisis extrema y recuperaci├│n total. Kit 100UI.',47,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-GH-009',14612,'https://anabolicgroup.com/product/hutrope-100-iu/');
INSERT INTO `products` VALUES (49,3,1,'Ibutamoren 15 mg','ibutamoren-15-mg','Masa Magra + Recuperaci├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Ibutamoren 15 mg</strong>┬á es un secretagogo de hormona de crecimiento oral en tabletas de 15 mg, que imita la ghrelina para estimular pulsos naturales de GH e IGF-1 (aumentos del 50-100%), promoviendo hipertrofia muscular (4-8 kg magros en 8-12 semanas), lip├│lisis sostenida y preservaci├│n muscular superior sin supresi├│n testosteronal ni inyecciones.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias densas de m├║sculo, recuperaci├│n acelerada (menos DOMS), sue├▒o profundo reparador (+20-30% REM), apetito controlado para bulk limpio, densidad ├│sea mejorada y piel/juventud rejuvenecida. Dosis: 10-25 mg/d├¡a nocturno (principiantes 15 mg), ciclos 8-16 semanas (PCT opcional). Stacks: + SARMs (LGD/Cardarine recomp), + Test (volumen GH), solo para TRT natural o anti-aging.</p>','',64.99,'USD','instock',1,'/static/img/ibutamoren-15-mg-29106.webp','Ibutamoren 15 mg : Masa Magra + Recuperaci├│n','Ibutamoren 15 mg: gana m├║sculo, mejora sue├▒o y quema grasa. Recuperaci├│n elite. ┬íPotencia hormonal natural!',48,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-GH-010',14265,'https://anabolicgroup.com/product/ibutamoren-15-mg/');
INSERT INTO `products` VALUES (50,3,2,'IGF-1 LR3 1 mg','igf-1-lr3-1-mg-xtlabs','Hiperplasia + Recuperaci├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>IGF-1 LR3 1 ml</strong>┬áes Insulina-like Growth Factor-1 Long R3 (p├®ptido sint├®tico 83 amino├ícidos, vida media 20-30h vs 20min IGF-1 natural), an├ílogo modificado no ligado a prote├¡nas de uni├│n que activa IGF-1R/mTOR directamente en m├║sculo/hueso, promoviendo┬á<strong>hiperplasia</strong>┬á(nuevas fibras musculares), s├¡ntesis proteica nuclear, reparaci├│n tejidos y lip├│lisis selectiva.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Hiperplasia muscular (+n├║cleos/fibras), hipertrofia explosiva (+5-10% masa 4 semanas), recuperaci├│n lesiones 50% m├ís r├ípida, quema grasa preservando m├║sculo, col├ígeno/tendones reforzados, neuroprotecci├│n. Dosis: 40-80 mcg post-entreno IM (bilateral deltoides/cu├ídriceps), 4-6 d├¡as/semana x 4 semanas (off 4 semanas); stacks: + HGH/MK677 (sinergia), + Test (anab├│lico).</p>','',120.00,'USD','outofstock',0,'/static/img/igf-1-lr3-1-ml-47047.webp','IGF-1 LR3 1 ml: Hiperplasia + Recuperaci├│n','IGF-1 LR3 1 ml: p├®ptido para nuevo m├║sculo (hiperplasia), reparaci├│n tejidos y quema grasa. Post-entreno IM. ┬íGen├®tica nueva!',49,'2026-11-18 16:52:26','2026-11-18 18:38:36','XTL-GH-011',14613,'https://anabolicgroup.com/product/igf-1-lr3-1-ml/');
INSERT INTO `products` VALUES (51,3,1,'Ligandrol 5 mg','ligandrol-5-mg','Masa Magra + Fuerza R├ípida','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Ligandrol 5 mg</strong>┬á(LGD-4033) es un modulador selectivo de receptores androg├®nicos (SARM) oral en tabletas de 5 mg, dise├▒ado para aumentar masa muscular magra (5-10 lbs en 4-8 semanas), mejorar fuerza funcional y preservar m├║sculo durante d├®ficits cal├│ricos, mediante uni├│n selectiva a receptores en m├║sculo y hueso, potenciando s├¡ntesis proteica, recuperaci├│n y densidad ├│sea sin efectos androg├®nicos prost├íticos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias r├ípidas de m├║sculo limpio, fuerza explosiva (+20-30% en entrenos), resistencia mejorada, quema grasa anticatab├│lica, recuperaci├│n acelerada y perfil seguro (menos supresi├│n que esteroides). Dosis hombres: 5-10 mg/d├¡a, mujeres: 2.5-5 mg/d├¡a; ciclos 8-12 semanas seguidas de PCT ligera (opcional: Nolva). Stacks: + Ostarine (recomp), + Cardarine (resistencia), + Test bajo (volumen) o solo para principiantes.</p>','',64.99,'USD','instock',1,'/static/img/ligandrol-5-mg-2227.webp','Ligandrol 5 mg : Masa Magra + Fuerza R├ípida','Ligandrol 5 mg: SARM para ganancias m├║sculo magro, fuerza elite y quema grasa. Recomposici├│n corporal.',50,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-012',14271,'https://anabolicgroup.com/product/ligandrol-5-mg/');
INSERT INTO `products` VALUES (52,3,2,'Mastaplex 100 mg','mastaplex-100-mg','Dureza + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Mastaplex 100 mg</strong>┬áes drostanolona propionato (Masteron premium) de XT Labs (100 mg/ml, vial 10 ml), derivado DHT inyectable de acci├│n corta (vida media 2-3 d├¡as), altamente androg├®nico (5x testosterona) no aromatizante, perfecto para cortes pre-competici├│n, promoviendo dureza extrema, vascularidad, lip├│lisis directa y definici├│n sin retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo gran├¡tico/densidad (+vascularidad 3D), fuerza seca (+20-30%), quema grasa metab├│lica, antiestrog├®nico (bloquea gyno), pumps intensos, recuperaci├│n mejorada. Dosis hombres: 300-500 mg/semana (EOD, 6-8 semanas); mujeres: 50-100 mg/semana. Stacks: + Tren/Winstrol (shredded), + Test Prop (base).</p>','',64.99,'USD','instock',1,'/static/img/mastaplex-100-mg-29310.webp','Mastaplex 100 mg: Dureza + Definici├│n','Mastaplex 100 mg: drostanolona propionato para m├║sculo rocoso, venas 3D y quema grasa sin estr├│genos. Vial 10ml.',51,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-DEF-013',14614,'https://anabolicgroup.com/product/mastaplex-100-mg/');
INSERT INTO `products` VALUES (53,3,1,'Methandroplex 20 mg','methandroplex-20-mg','Volumen R├ípido + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Methandroplex 20 mg</strong>┬áes metandrostenolona (Dianabol) premium de XT Labs en tabletas de 20 mg, el anab├│lico oral cl├ísico para ciclos de volumen explosivo, maximizando s├¡ntesis proteica, retenci├│n de nitr├│geno y glucogen├│lisis para hipertrofia r├ípida (8-15 kg en 4-6 semanas), pumps masivos y fuerza sobrehumana (+30-50% en compuestos), perfecto como kickstart mientras inyectables satur├ín.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Crecimiento muscular inmediato (pecho/espalda full), apetito voraz, recuperaci├│n elite, energ├¡a ATP superior y \"feel good\" hormonal. Dosis: 20-50 mg/d├¡a dividido (principiantes 20-40 mg), ciclos 4-6 semanas m├íx. (hepatot├│xico: usa Silimarina). Stacks: + Test/Deca (masa extrema), + EQ (calidad), solo para novatos o shock. No para mujeres (virilizaci├│n). M├®dicamente para caquexia o fortalecimiento.</p>','',64.99,'USD','instock',1,'/static/img/methandroplex-20-mg.webp','Methandroplex 20 mg: Volumen R├ípido + Fuerza','Methandroplex 20 mg: Dianabol oral para ganancias masivas m├║sculo y fuerza brutal. Kickstart ciclos.',52,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-014',14274,'https://anabolicgroup.com/product/methandroplex-20mg/');
INSERT INTO `products` VALUES (54,3,2,'Nandroplex 100 mg','nandroplex-100-mg','Masa R├ípida + Articulaciones','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Nandroplex 100 mg</strong>┬áes fenilpropionato de nandrolona (NPP) inyectable de XT Labs (100 mg/ml vial 10ml), versi├│n de acci├│n r├ípida (3-4 d├¡as) del cl├ísico Deca, altamente anab├│lica con bajo androg├®nico, perfecta para ciclos de volumen magro, recuperaci├│n articular superior y ganancias s├│lidas (6-10 kg en 8 semanas) sin retenci├│n excesiva de agua.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: S├¡ntesis proteica intensa, retenci├│n nitr├│geno, eritropoyesis (m├ís ox├¡geno), col├ígeno articular (lubricaci├│n tendones), inmunidad reforzada y menos aromatizaci├│n que testosterona. Dosis hombres: 200-400 mg/semana IM (EOD), mujeres: 50-100 mg/semana; ciclos 8-12 semanas. Stacks: + Test (masa conjunta), + Dianabol (kickstart), solo para soporte articular o TRT. M├®dicamente para anemia/osteoporosis.</p>','',64.99,'USD','outofstock',0,'/static/img/nandroplex-100-mg.webp','Nandroplex 100 mg: Masa R├ípida + Articulaciones','Nandroplex 100 mg: nandrolona fenilpropionato para m├║sculo magro, recuperaci├│n articular y fuerza. Acci├│n r├ípida. ┬íVolumen sin dolor!',53,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-015',14230,'https://anabolicgroup.com/product/nandroplex-100-mg/');
INSERT INTO `products` VALUES (55,3,1,'Ostarine 10 mg','ostarine-10-mg','Masa Magra + Fuerza Segura','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Ostarine 10 mg</strong>┬áes un SARM selectivo oral en tabletas de 10 mg que une receptores androg├®nicos en m├║sculo y hueso, promoviendo hipertrofia magra (3-7 kg en 8 semanas), preservaci├│n muscular en d├®ficits cal├│ricos y fuerza funcional sin efectos androg├®nicos sist├®micos ni supresi├│n hormonal severa, perfecto para recomp, corte o bulk limpio.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Aumento lean mass, p├®rdida grasa anticatab├│lica, endurance mejorada, densidad ├│sea superior, recuperaci├│n r├ípida y perfil suave (mujeres/principiantes ideal). Dosis: 10-25 mg/d├¡a (10 mg principiantes), ciclos 8-12 semanas (PCT ligera opcional). Stacks: + Cardarine (endurance), + Ligandrol (volumen), + Test bajo (recomp) o solo para iniciaci├│n SARM.</p>','',64.99,'USD','instock',1,'/static/img/ostarine-10-mg.webp','Ostarine 10 mg: Masa Magra + Fuerza Segura','Ostarine 10 mg: SARM para m├║sculo magro, quema grasa y recuperaci├│n elite. Ideal principiantes.',54,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-016',14262,'https://anabolicgroup.com/product/ostarine-10-mg/');
INSERT INTO `products` VALUES (56,3,1,'Oxandroplex 10 mg Oxandrolona','oxandroplex-10-mg-oxandrolona','Definici├│n + Fuerza Magra','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Oxandroplex 10 mg</strong>┬áes oxandrolona (Anavar gen├®rico) en tabletas de 10 mg, el anab├│lico oral m├ís seguro para ciclos de corte, recomposici├│n y preservaci├│n muscular, estimulando s├¡ntesis proteica, retenci├│n de nitr├│geno y lip├│lisis selectiva para ganancias magras (3-6 kg), reducci├│n de grasa (5-10% BF en 6-8 semanas) y dureza vascular sin retenci├│n h├¡drica ni efectos androg├®nicos fuertes.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo compacto y definido, fuerza progresiva (+15-25% sin bulk), recuperaci├│n r├ípida, bajo hepatot├│xico/androg├®nico (ideal mujeres 5-20 mg/d├¡a), pumps notables y sinergia en stacks. Dosis hombres: 20-50 mg/d├¡a dividido, mujeres: 10-30 mg/d├¡a; ciclos 6-10 semanas. Stacks: solo (corte seguro), + Winstrol (dureza extrema), + Test bajo (recomp), + Clen/T3 (quema grasa) o + Primo (calidad pro). M├®dicamente para caquexia o recuperaci├│n.</p>','',64.99,'USD','instock',1,'/static/img/oxandroplex-10-mg-oxandrolona.webp','Oxandroplex 10 mg Oxandrolona: Definici├│n + Fuerza Magra','Oxandroplex 10 mg: oxandrolona para m├║sculo magro, quema grasa y fuerza sin agua. Seguro mujeres/hombres.',55,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-DEF-017',14283,'https://anabolicgroup.com/product/oxandroplex-10mg/');
INSERT INTO `products` VALUES (57,3,1,'Oxyplex 50 mg','oxyplex-50-mg','Volumen Explosivo + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Oxiplex 50 mg</strong>┬áes oximetolona (Anadrol premium) de XT Labs (50 mg/tableta, 60 tabs), esteroide oral 17-alfa alquilado derivado DHT (anab├│lico 320%, androg├®nico 45%), perfecto para ciclos de volumen explosivo y kickstarts, con retenci├│n nitr├│geno extrema, s├¡ntesis proteica nuclear y eritropoyesis para ganancias r├ípidas (7-15 kg en 4 semanas), pumps intensos y apetito voraz.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Hipertrofia masiva/fullness (visibles d├¡a 3), fuerza sobrehumana (+40-60% compuestos), recuperaci├│n horas, RBCÔåæ (oxigenaci├│n), inmunidad reforzada. Dosis: 50-100 mg/d├¡a (dividido, 4-6 semanas m├íximo); stacks: + Test/Deca (masa extrema). Mujeres evitar. <strong>┬á</strong></p>','',58.99,'USD','instock',1,'/static/img/oxiplex-50-mg.webp','Oxiplex 50 mg: Volumen Explosivo + Fuerza','Oxiplex 50 mg: oximetolona oral para ganancias masivas (10kg+ 4 semanas), pumps brutales y apetito voraz.',56,'2026-11-18 16:52:26','2026-11-18 18:38:36','XTL-VOL-018',14632,'https://anabolicgroup.com/product/oxiplex-50-mg/');
INSERT INTO `products` VALUES (58,3,2,'Primoplex 100 mg','primoplex-100-mg','Masa Limpia + Definici├│n','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Primoplex 100 mg</strong>┬áes metenolona enantato (Primobolan) inyectable de XT Labs (100 mg/ml vial 10ml), derivado DHT suave de acci├│n prolongada (10-14 d├¡as), perfecto para ciclos de corte, recomposici├│n y ganancias de masa muscular de alta calidad sin retenci├│n h├¡drica, aromatizaci├│n ni efectos estrog├®nicos, preservando m├║sculo magro durante d├®ficits cal├│ricos extremos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo denso/vascular (3-7 kg quality), lip├│lisis selectiva, fuerza progresiva sin bulk, perfil seguro (bajo androg├®nico/hepatot├│xico), inmunidad reforzada y sinergia en stacks avanzados. Dosis hombres: 400-800 mg/semana IM, mujeres: 100-200 mg/semana; ciclos 10-16 semanas. Stacks: + Test (recomp seguro), + Winstrol/Masteron (corte pro), + Tren (elite) o solo para definici├│n limpia.</p>','',74.99,'USD','outofstock',0,'/static/img/primoplex-100-mg.webp','Primoplex 100 mg: Masa Limpia + Definici├│n','Primoplex 100 mg: metenolona enantato para m├║sculo magro, quema grasa sin agua.',57,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-019',14241,'https://anabolicgroup.com/product/primoplex-100-mg/');
INSERT INTO `products` VALUES (59,3,2,'Razor 200 mg','razor-200-mg','Corte Extremo + Dureza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Razor 200 mg</strong>┬áes la mezcla inyectable \"cutting\" definitiva de XT Labs (200 mg/ml vial 10ml: Testosterona Propionato 100 mg + Drostanolona Propionato/Masteron 50 mg + Trembolona Acetato 50 mg), combinando anabolismo r├ípido de test prop, anti-estrog├®nico/dureza de Masteron y potencia nuclear de Tren Ace para recomposici├│n extrema sin m├║ltiples inyecciones.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: F├¡sico vascular 3D/rocoso, lip├│lisis directa (+15-25% metabolismo), fuerza brutal (+40-60%), m├║sculo ultra-compacto, pumps intensos y cero retenci├│n h├¡drica. Dosis avanzados: 400-600 mg/semana IM EOD (1-1.5 ml), ciclos 6-8 semanas m├íximo. Stacks: solo (perfecto), + orales Winstrol/Anavar (pro), + HGH (elite). No principiantes/mujeres.</p>','',74.99,'USD','instock',1,'/static/img/razor-200-mg.webp','Razor 200 mg: Corte Extremo + Dureza','Razor 200 mg: mezcla Test Prop + Masteron + Tren Ace para f├¡sico rasgado, quema grasa y fuerza sin agua.',58,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-DEF-020',14447,'https://anabolicgroup.com/product/razor-200mg/');
INSERT INTO `products` VALUES (60,3,1,'Stanoplex 10 mg Estanozolol','stanoplex-10-mg-estanozolol','Definici├│n Dura + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Stanoplex 10 mg</strong>┬áes estanozolol (Winstrol oral) en tabletas de 10 mg, un derivado DHT potente para fases de corte agresivo, promoviendo lip├│lisis intensa, preservaci├│n muscular extrema y dureza gran├¡tica sin retenci├│n h├¡drica ni aromatizaci├│n, ideal para physiques pre-competici├│n con vascularidad 3D y definici├│n elite (p├®rdida 1-2% BF/semana en d├®ficit).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Reducci├│n grasa subcut├ínea, fuerza explosiva (+20-30% compuestos), m├║sculo compacto (2-5 kg magros), pumps vasculares notables, resistencia aer├│bica superior y sinergia anti-catab├│lica. Dosis hombres: 25-50 mg/d├¡a dividido, mujeres: 10-20 mg/d├¡a; ciclos 6-8 semanas m├íx. (hepatot├│xico moderado). Stacks: + Anavar (corte seguro), + Masteron/Tren (dureza pro), + Test bajo (recomp) o + Clen (quema extrema). M├®dicamente para angioedema o densidad ├│sea.</p>','',59.99,'USD','instock',1,'/static/img/stanoplex-10-mg-estanozolol.webp','Stanoplex 10 mg Estanozolol: Definici├│n Dura + Fuerza','Stanoplex 10 mg: estanozolol para m├║sculo seco, quema grasa y venas marcadas. Fuerza sin agua.',59,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-DEF-021',14280,'https://anabolicgroup.com/product/stanoplex-10mg-60tab/');
INSERT INTO `products` VALUES (61,3,2,'Stanoplex 10 ml','stanoplex-10-ml','Definici├│n Dura + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Stanoplex 10 ml</strong>┬áes estanozolol (Winstrol inyectable) de XT Labs (100 mg/ml vial 10ml), derivado DHT de acci├│n media (24-48h) menos hepatot├│xico que oral, perfecto para fases de corte extremo, promoviendo lip├│lisis acelerada, dureza muscular gran├¡tica y vascularidad pronunciada sin retenci├│n h├¡drica ni aromatizaci├│n, reduciendo SHBG para potenciar otros compuestos en stack.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: P├®rdida grasa rebelde (1-2% BF/semana), fuerza explosiva (+20-35% sin bulk), m├║sculo compacto preservado, potencia/velocidad atl├®tica, pumps vasculares elite y sinergia anab├│lica. Dosis hombres: 200-400 mg/semana IM (EOD), mujeres: 50-100 mg/semana; ciclos 6-8 semanas. Stacks: + Test/Primo (recomp), + Masteron/Tren (corte pro), + Clen (quema grasa) o solo definici├│n.</p>','',64.99,'USD','instock',1,'/static/img/stanoplex-10-ml.webp','Stanoplex 10 ml: Definici├│n Dura + Fuerza','Stanoplex 10 ml: estanozolol inyectable para m├║sculo seco, venas marcadas y potencia sin agua. Menos h├¡gado estr├®s.',60,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-DEF-022',14236,'https://anabolicgroup.com/product/stanoplex-10ml/');
INSERT INTO `products` VALUES (62,3,2,'Sustaplex 275 mg','sustaplex-275-mg','Volumen Constante + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Sustaplex 275 mg</strong>┬áes una mezcla inyectable premium de XT Labs (275 mg/ml vial 10ml: propionato, fenilpropionato, isocaproato y decanoato de testosterona), dise├▒ada para liberaci├│n escalonada que mantiene niveles hormonales estables durante 3-4 semanas por dosis, ideal para ciclos de volumen progresivo, fuerza continua y rendimiento sostenido sin picos/valores bajos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias musculares constantes (10-18 kg en 10-12 semanas), fuerza m├íxima progresiva (+30-50%), recuperaci├│n superior, libido/energ├¡a elevada, retenci├│n nitr├│geno y versatilidad TRT/volumen. Dosis: 275-550 mg/semana IM (1 ml/semana principiantes), ciclos 10-14 semanas. Stacks: + Deca (masa extrema), + Dianabol (kickstart), + EQ/Tren (calidad) o solo base.</p>','',64.99,'USD','instock',1,'/static/img/sustaplex-275-mg.webp','Sustaplex 275 mg: Volumen Constante + Fuerza','Sustaplex 275 mg: mezcla testosteronas para masa sostenida, fuerza progresiva y recuperaci├│n elite.',61,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-023',14218,'https://anabolicgroup.com/product/sustaplex-275-mg-volumen-constante-fuerza/');
INSERT INTO `products` VALUES (63,3,2,'Triple XXX 200 mg Tritrenbolona','triple-xxx-200-mg-tritrenbolona','Masa Dura + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Triple XXX 200 mg</strong>┬áes una mezcla potente de tres ├®steres de trembolona (acetato, enantato, hexahidrobencilcarbonato) de XT Labs en vial de 10 ml (200 mg/ml), considerada el esteroide m├ís vers├ítil y anab├│lico (5x testosterona) para ciclos de volumen seco, corte extremo y fuerza sobrehumana, promoviendo s├¡ntesis proteica masiva, lip├│lisis directa, eritropoyesis y retenci├│n de nitr├│geno sin retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias magras de calidad (10-15 kg retenidas), dureza rocosa/vascularidad 3D, fuerza explosiva (+40-60% compuestos), quema grasa simult├ínea, gluc├│geno/creatina muscular elevados y recuperaci├│n elite. Dosis: 400-600 mg/semana IM (principiantes 1 ml/semana), ciclos 8-12 semanas. Stacks: + Test (base), + Masteron/Winstrol (corte pro), + EQ/Deca (volumen) o solo para avanzados.</p>','',79.99,'USD','instock',1,'/static/img/triple-xxx-200-mg-tritrenbolona.webp','Triple XXX 200 mg Tritrenbolona: Masa Dura + Fuerza','Triple XXX 200 mg: tritrenbolona para m├║sculo rocoso, quema grasa y fuerza brutal sin agua. Elite corte/volumen.',62,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-024',14259,'https://anabolicgroup.com/product/triple-xxx-200-mg/');
INSERT INTO `products` VALUES (64,3,2,'TVR 350 mg Testo Enantato/Propionato','tvr-350-mg-testo-enantato-propionato','Volumen + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>TVR 350 mg</strong>┬áes una mezcla inyectable vers├ítil de XT Labs (350 mg/ml vial 10ml: 250 mg testosterona enantato + 100 mg testosterona propionato), combinando acci├│n r├ípida del propionato (efectos desde semana 1) con liberaci├│n prolongada del enantato (hasta 2 semanas), perfecta para ciclos de volumen, fuerza m├íxima y recomposici├│n con ganancias permanentes f├íciles de mantener (10-15 kg en 10 semanas).</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Aumento explosivo de masa muscular, fuerza sobrehumana (+30-50% compuestos), resistencia mejorada, recuperaci├│n elite, libido elevada y versatilidad volumen/definici├│n. Dosis: 350-700 mg/semana IM (1 ml 2-3x/semana principiantes), ciclos 10-12 semanas. Stacks: + Deca/Dianabol (masa extrema), + EQ (calidad), solo como base o TRT. Efectos testosterona cl├ísicos.</p>','',74.99,'USD','outofstock',0,'/static/img/tvr-350-mg-testo-enantato-propionato.webp','TVR 350 mg Testo Enantato/Propionato: Volumen + Fuerza','TVR 350 mg: mezcla testosterona para ganancias masivas m├║sculo, fuerza inmediata y recuperaci├│n. Acci├│n r├ípida.',63,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-025',14253,'https://anabolicgroup.com/product/tvr-350-mg-testo-enantato-propionato/');
INSERT INTO `products` VALUES (65,3,2,'TXT 400 mg','txt-400-mg','Volumen + Fuerza','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>TXT 400 mg</strong>┬áes mezcla avanzada de testosteronas de XT Labs (400 mg/ml vial 10 ml: ~175mg cipionato, 175mg enantato, 50mg decanoato/ciclopentilpropionato), blend inyectable de acci├│n mixta (r├ípida + prolongada, vida media 7-15 d├¡as), base suprema para ciclos de volumen/fuerza, promoviendo s├¡ntesis proteica m├íxima, retenci├│n nitr├│geno, eritropoyesis y libido con menos picos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias brutales (20kg+ ciclo), fuerza explosiva (+40-60%), pumps fullness, recuperaci├│n total, menos inyecciones (1x/semana), vers├ítil bulk/corte. Dosis: 400-800 mg/semana (10-16 semanas); stacks: + Deca/Dbol (masa), + Tren (recomp).</p>','',74.99,'USD','outofstock',0,'/static/img/txt-400-mg.webp','TXT 400 mg: Volumen + Fuerza','TXT 400 mg: mezcla testosterona (Cyp/Prop/Deca) para ganancias masivas, liberaci├│n sostenida y menos inyecciones. Vial 10ml.',64,'2026-11-18 16:52:26','2026-11-18 17:34:29','XTL-VOL-026',14656,'https://anabolicgroup.com/product/txt-400-mg/');
