INSERT INTO `products` VALUES (90,3,2,'Testoplex-E 300 mg','testoplex-e-300-mg','Testoplex-E 300 mg: enantato testosterona para masa (+20kg ciclo), fuerza brutal y libido. Vial 10ml.','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Testoplex-E 300 mg</strong>┬áes enantato de testosterona (Test E premium) de XT Labs (300 mg/ml, vial 10 ml), ├®ster largo inyectable (vida media 7-10 d├¡as), hormona anab├│lica/androg├®nica rey (rating 100:100), perfecto para ciclos de volumen off-season y TRT, con liberaci├│n sostenida que maximiza s├¡ntesis proteica, retenci├│n nitr├│geno, eritropoyesis y anabolismo general.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias masivas (15-25kg), fuerza dram├ítica (+40-60% lifts), pumps fullness, recuperaci├│n post-entreno horas, libido/energ├¡a/confianzaÔåæ, hueso/densidadÔåæ, quema grasa androg├®nica. Dosis: 300-600 mg/semana (1-2 inyecciones, 10-16 semanas); stacks: + Deca/Dbol (bulk), + Tren/Anavar (recomp).</p>','',44.99,'USD','instock',1,'/static/img/testoplex-e-300-mg.webp','Testoplex-E 300 mg: Volumen + Fuerza Elite','Testoplex-E 300 mg: enantato testosterona para masa (+20kg ciclo), fuerza brutal y libido. Vial 10ml.',89,'2026-11-18 16:52:27','2026-11-18 17:34:29','XTL-VOL-037',14643,'https://anabolicgroup.com/product/testoplex-e-300-mg/');
INSERT INTO `products` VALUES (91,3,2,'Titan 400 mg','titan-400-mg','Titan 400 mg: mezcla Testo, Masteron y Tren para m├║sculo rocoso, quema grasa y potencia brutal. Todo-en-uno elite.','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Titan 400 mg</strong>┬áes una mezcla inyectable \"todo en uno\" de XT Labs (400 mg/ml vial 10ml: testosterona enantato, drostanolona enantato, trembolona enantato), dise├▒ada para ciclos de recomposici├│n avanzada, combinando anabolismo masivo de testosterona y trenbolona con anti-estrog├®nico/dureza de drostanolona para ganancias magras (8-15 kg retenidas), vascularidad 3D y fuerza sobrehumana sin m├║ltiples pinchazos.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Hipertrofia densa/rocosa, lip├│lisis directa (+tasa metab├│lica), fuerza explosiva (+40-60%), recuperaci├│n elite, libido elevada y sinergia equilibrada (Mast mitiga E2 de Test/Tren). Dosis: 400-800 mg/semana IM (1-2 ml/semana avanzados), ciclos 10-12 semanas. Stacks: solo (ideal busy), + orales (kickstart), + HGH (elite) o PCT intensiva.</p>','',79.99,'USD','outofstock',0,'/static/img/titan-400-mg.webp','Titan 400 mg : Masa Dura + Fuerza','Titan 400 mg: mezcla Testo, Masteron y Tren para m├║sculo rocoso, quema grasa y potencia brutal. Todo-en-uno elite.',90,'2026-11-18 16:52:27','2026-11-18 17:34:29','XTL-VOL-038',14256,'https://anabolicgroup.com/product/titan-400-mg-masa/');
INSERT INTO `products` VALUES (93,1,2,'Decaprime 200 mg','decaprime-200-mg','Decaprime 200 mg: nandrolona decanoato para masa (+15kg ciclo), recuperaci├│n joints y col├ígeno. 10 amps 1ml.','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Decaprime 200 mg</strong>┬áes decanoato de nandrolona (Deca premium) de Eminence Labs (200 mg/ml, 10 ampollas x 1 ml), esteroide inyectable 19-nor de acci├│n prolongada (vida media 15 d├¡as), suave androg├®nico (37% testosterona) con alta actividad anab├│lica, perfecto para ciclos de volumen off-season y terap├®utica articular, promoviendo retenci├│n nitr├│geno extrema, s├¡ntesis proteica sostenida, lubricaci├│n sinovial y eritropoyesis sin aromatizaci├│n fuerte.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Ganancias magras (10-20kg ciclo), articulaciones blindadas (col├ígenoÔåæ + sinovitis Ôåô), recuperaci├│n brutal, inmunidad reforzada, RBCÔåæ (resistencia), apetito controlado. Dosis: 400-600 mg/semana (1-2 inyecciones, 10-12 semanas); stacks: + Test Long (cl├ísico), + Dianabol (kickstart), + Tren (masa pro). Mujeres bajas dosis.</p>','',59.99,'USD','outofstock',0,'/static/img/decaprime-200-mg-23268.webp','Decaprime 200 mg: Volumen Magro + Articulaciones','Decaprime 200 mg: nandrolona decanoato para masa (+15kg ciclo), recuperaci├│n joints y col├ígeno. 10 amps 1ml.',92,'2026-11-18 16:52:27','2026-11-18 17:34:29','EMI-VOL-017',14493,'https://anabolicgroup.com/product/decaprime-200-mg/');
INSERT INTO `products` VALUES (94,1,2,'Decaprime NPP 100 mg','decaprime-npp-100-mg','<b>Decaprime NPP 100 mg</b> (Nandrolona Fenilpropionato, NPP) de la marca <b>Eminence Labs</b>: volumen magro, recuperacion articular y fuerza solida.','<h2>Decaprime NPP 100 mg: Volumen Rapido + Articulaciones</h2>\n<p>El <b>Decaprime NPP 100 mg</b> (Nandrolona Fenilpropionato, NPP) de la marca <b>Eminence Labs</b> es la version de accion rapida del clasico Deca (Nandrolona Decanoato). Con ester fenilpropionato de vida media corta (2-4 dias), genera volumen limpio, masa magra y una marcada lubricacion articular, ideal para ciclos de ganancia solida con minima retencion hidrica y recuperacion rapida entre dosis.</p>\n\n<h3>Beneficios Principales</h3>\n<ul>\n<li><b>Masa Muscular Magra:</b> Estimula la sintesis proteica favoreciendo ganancias de calidad (musculo denso, sin hinchazon excesiva).</li>\n<li><b>Recuperacion Articular y Tendinosa:</b> Mejora el colageno y el trofismo de cartilagos y tendones, ideal bajo cargas pesadas.</li>\n<li><b>Accion Rapida:</b> Su ester corto entra y sale del organismo mas rapido que el decanoato, permitiendo control y ajustes de dosis mas precisos.</li>\n<li><b>Fuerza Sostenida:</b> Aporte anabolico constante que se traduce en progresion en el entrenamiento.</li>\n</ul>\n\n<h3>Ficha Tecnica y Especificaciones</h3>\n<table>\n<thead>\n<tr><td><strong>Caracteristica</strong></td><td><strong>Detalle</strong></td></tr>\n</thead>\n<tbody>\n<tr><td><strong>Concentracion</strong></td><td>100 mg/ml</td></tr>\n<tr><td><strong>Formato</strong></td><td>Vial 10 ml</td></tr>\n<tr><td><strong>Compuesto</strong></td><td>Nandrolona Fenilpropionato (NPP)</td></tr>\n<tr><td><strong>Marca</strong></td><td>Eminence Labs</td></tr>\n<tr><td><strong>Via de administracion</strong></td><td>Inyeccion intramuscular</td></tr>\n<tr><td><strong>Ciclo tipico</strong></td><td>8 a 12 semanas</td></tr>\n<tr><td><strong>Almacenamiento</strong></td><td>Lugar fresco y seco, protegido de la luz</td></tr>\n</tbody>\n</table>\n\n<h4>Uso Recomendado (Referencial)</h4>\n<p>Hombres: 200-400 mg/semana administrados en dias alternos. Mujeres: 50-100 mg/semana. Puede combinarse con testosterona o esteres orales segun el objetivo del ciclo. La dosis y la duracion deben ser evaluadas por un profesional de la salud calificado.</p>\n\n<h4>Disclaimer:</h4>\n<p>Este producto se distribuye con fines informativos y/o de investigacion. Su uso debe ser evaluado, prescrito y supervisado por un profesional de la salud calificado. No automedicarse. Su uso esta supeditado a la completa responsabilidad del comprador.</p>','',59.99,'USD','instock',1,'/static/img/decaprime-npp-100-mg-82563.jpg','Decaprime NPP 100 mg: Volumen Rapido + Articulaciones','<b>Decaprime NPP 100 mg</b> (Nandrolona Fenilpropionato, NPP) de la marca <b>Eminence Labs</b>: volumen magro, recuperacion articular y fuerza solida.',93,'2026-11-18 16:52:27','2026-11-18 17:34:29','EMI-VOL-018',14491,'https://anabolicgroup.com/product/dacaprime-npp-100-mg/');
INSERT INTO `products` VALUES (95,1,2,'Drostoprime 100 mg','drostoprime-100-mg','Drostoprime 100 mg: drostanolona propionato para m├║sculo gran├¡tico, venas 3D y quema grasa sin estr├│genos. 10 amps 1ml.','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Drostoprime 100 mg</strong>┬áes drostanolona propionato (Masteron premium) de Eminence Labs (100 mg/ml, 10 ampollas x 1 ml), derivado DHT inyectable de acci├│n corta (vida media 2-3 d├¡as), potente androg├®nico no aromatizante, perfecto para fases de corte pre-competici├│n, promoviendo dureza muscular extrema, definici├│n vascular, lip├│lisis directa y balance nitr├│geno positivo sin retenci├│n h├¡drica.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: Densidad muscular rocosa (+ vascularidad 3D), fuerza seca (+20-30%), quema grasa metab├│lica, antiestrog├®nico natural (bloquea gyno), pumps intensos, recuperaci├│n r├ípida. Dosis hombres: 300-500 mg/semana (EOD, 6-8 semanas); mujeres: 50-100 mg/semana (4-6 semanas). Stacks: + Tren/Winstrol (shredded pro), + Test Prop (base corte).</p>','',58.99,'USD','instock',1,'/static/img/drostoprime-100-mg-71000.webp','Drostoprime 100 mg: Dureza Extrema + Definici├│n','Drostoprime 100 mg: drostanolona propionato para m├║sculo gran├¡tico, venas 3D y quema grasa sin estr├│genos. 10 amps 1ml.',94,'2026-11-18 16:52:27','2026-11-18 17:34:29','EMI-DEF-019',14494,'https://anabolicgroup.com/product/drostoprime-100-mg/');
INSERT INTO `products` VALUES (96,1,2,'Trenoprime 100 mg','trenoprime-100-mg','Trenoprime 100 mg: trembolona acetato para m├║sculo rocoso, quema grasa extrema y potencia sobrehumana.','<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Trenoprime 100 mg</strong>┬áes acetato de trembolona (Tren Ace premium) de Eminence Labs (100 mg/ml, 10 ampollas x 1ml), esteroide anab├│lico 5x m├ís potente que testosterona, derivado nandrolona de acci├│n corta (2-3 d├¡as), perfecto para ciclos de corte extremo y recomposici├│n, promoviendo lip├│lisis directa, dureza muscular gran├¡tica, vascularidad 3D y fuerza sobrehumana (+50-70% compuestos) sin retenci├│n h├¡drica ni aromatizaci├│n.</p>\r\n<p class=\"my-2 [&amp;+p]:mt-4 [&amp;_strong:has(+br)]:inline-block [&amp;_strong:has(+br)]:pb-2\"><strong>Beneficios clave</strong>: M├║sculo ultra-compacto (p├®rdidas m├¡nimas PCT), quema grasa visceral sin dieta dr├ística, pumps vasculares intensos, recuperaci├│n en horas, IGF-1 elevado y metabolismo proteico elite. Dosis avanzados: 300-500 mg/semana IM EOD (0.5-1 ml), ciclos 6-8 semanas m├íximo. Stacks: + Test/Primo (base segura), + Winstrol/Masteron (corte pro), nunca solo.</p>','',59.99,'USD','instock',1,'/static/img/trenoprime-100-mg.webp','Trenoprime 100 mg: Fuerza Nuclear + Definici├│n','Trenoprime 100 mg: trembolona acetato para m├║sculo rocoso, quema grasa extrema y potencia sobrehumana.',95,'2026-11-18 16:52:27','2026-11-18 17:34:29','EMI-DEF-020',14549,'https://anabolicgroup.com/product/trenoprime-100-mg/');
